export const SOURCES: Source[] = [
  {"id":"R01","year":2026,"authors":"Currier et al. / ACSM","title":"American College of Sports Medicine Position Stand. Resistance Training Prescription for Muscle Function, Hypertrophy, and Physical Performance in Healthy Adults: An Overview of Reviews","journal":"Medicine & Science in Sports & Exercise 58(4):851-872","doi":"10.1249/MSS.0000000000003897","url":"https://pubmed.ncbi.nlm.nih.gov/41843416/","finding":"Progressive resistance training improves multiple outcomes. Regular training of major muscle groups is the foundation; prescriptions should reflect the goal.","limit":"Broad support for home and gym modes; strongest evidence for programming principles, not a ranking of individual exercises. The 2026 publication does not itself include all 2025-26 research."},
  {"id":"R02","year":2026,"authors":"Pelland et al.","title":"The Resistance Training Dose Response: Meta-Regressions Exploring the Effects of Weekly Volume and Frequency on Muscle Hypertrophy and Strength Gains","journal":"Sports Medicine 56:481-505; online December 4, 2025","doi":"10.1007/s40279-025-02344-w","url":"https://link.springer.com/article/10.1007/s40279-025-02344-w","finding":"More weekly sets predicted greater gains with diminishing returns. Frequency had a clearer independent relationship with strength than with hypertrophy. Fractional accounting for indirect sets fitted the data best.","limit":"Support adjustable weekly volume and distinguish direct from indirect work. A 0.5 contribution is a modeling convention, not a universal biological conversion."},
  {"id":"R03","year":2023,"authors":"Currier et al.","title":"Resistance training prescription for muscle strength and hypertrophy in healthy adults: a systematic review and Bayesian network meta-analysis","journal":"British Journal of Sports Medicine 57:1211-1220","doi":"10.1136/bjsports-2023-106807","url":"https://pubmed.ncbi.nlm.nih.gov/37414459/","finding":"Many prescriptions improved outcomes. Heavier loading was especially relevant to maximal strength; multiple sets were useful for hypertrophy.","limit":"Provide strength and muscle-growth settings without making a single rep range the only effective choice. Network rankings do not prove one universal best program."},
  {"id":"R04","year":2025,"authors":"Zhang et al.","title":"Superset Versus Traditional Resistance Training Prescriptions: A Systematic Review and Meta-analysis Exploring Acute and Chronic Effects on Mechanical, Metabolic, and Perceptual Variables","journal":"Sports Medicine 55:953-975","doi":"10.1007/s40279-025-02176-8","url":"https://pubmed.ncbi.nlm.nih.gov/39903375/","finding":"Supersets shortened sessions and generally preserved adaptations, while raising perceived effort. Same-muscle pairings could reduce completed training volume.","limit":"Offer noncompeting pairs as a time-saving option. The chronic evidence is smaller than the total study count; preserve performance and recovery."},
  {"id":"R05","year":2021,"authors":"Iversen et al.","title":"No Time to Lift? Designing Time-Efficient Training Programs for Strength and Hypertrophy: A Narrative Review","journal":"Sports Medicine 51:2079-2095","doi":"10.1007/s40279-021-01490-1","url":"https://pubmed.ncbi.nlm.nih.gov/34125411/","finding":"Bilateral multijoint exercises, selective warm-ups, and economical set structures can reduce the time burden.","limit":"A useful design framework, not a trial validating a particular 20-minute app routine. Avoid assuming unilateral work is always the best upgrade."},
  {"id":"R06","year":2025,"authors":"Without Fail trial","title":"Without Fail: Muscular Adaptations in Single-Set Resistance Training Performed to Failure or with Repetitions-in-Reserve","journal":"Medicine & Science in Sports & Exercise 57(9):2021-2031","doi":"10.1249/MSS.0000000000003728","url":"https://pubmed.ncbi.nlm.nih.gov/40249908/","finding":"Both failure and two-repetitions-in-reserve groups improved most outcomes. Some muscle-growth outcomes modestly favored failure; strength changes were similar.","limit":"Justifies a low-volume fallback. It does not establish that one set maximizes gains or that a shorter four-exercise plan reproduces this trial."},
  {"id":"R07","year":2024,"authors":"Robinson et al.","title":"Exploring the Dose-Response Relationship Between Estimated Resistance Training Proximity to Failure, Strength Gain, and Muscle Hypertrophy: A Series of Meta-Regressions","journal":"Sports Medicine 54:2209-2231","doi":"10.1007/s40279-024-02069-2","url":"https://pubmed.ncbi.nlm.nih.gov/38970765/","finding":"Training closer to failure was associated with more hypertrophy; strength gains were less sensitive across the studied range.","limit":"Teach effort and use challenging sets, but do not force failure or describe a precise RIR cutoff as settled science."},
  {"id":"R08","year":2023,"authors":"Free-weight versus machine meta-analysis","title":"Effect of free-weight vs. machine-based strength training on maximal strength, hypertrophy and jump performance - a systematic review and meta-analysis","journal":"BMC Sports Science, Medicine and Rehabilitation","doi":"10.1186/s13102-023-00713-4","url":"https://link.springer.com/article/10.1186/s13102-023-00713-4","finding":"No clear hypertrophy advantage for either mode; strength improvements were substantially specific to the trained and tested mode.","limit":"Machines belong in the main gym pool. This is not proof that every machine and free-weight variation is equivalent, or that one mode is universally safer."},
  {"id":"R09","year":2019,"authors":"Lopes et al.","title":"Effects of training with elastic resistance versus conventional resistance on muscular strength: A systematic review and meta-analysis","journal":"SAGE Open Medicine","doi":"10.1177/2050312119831116","url":"https://pubmed.ncbi.nlm.nih.gov/30815258/","finding":"Elastic resistance can improve strength with broadly comparable results to conventional resistance in the included comparisons.","limit":"Bands are a legitimate home option. Evidence here concerns strength, not proof of equal hypertrophy for every band exercise. Standardize anchor position and band setup."},
  {"id":"R10","year":2017,"authors":"Kikuchi and Nakazato","title":"Low-load bench press and push-up induce similar muscle hypertrophy and strength gain","journal":"Journal of Exercise Science & Fitness","doi":"10.1016/j.jesf.2017.06.003","url":"https://pubmed.ncbi.nlm.nih.gov/29541130/","finding":"The groups had similar muscle-growth and strength improvements under the tested conditions.","limit":"Keep scalable push-ups as a principal home chest exercise. Small, narrow trial; do not extrapolate to equal maximal-strength outcomes at every ability level."},
  {"id":"R11","year":2021,"authors":"Maeo et al.","title":"Greater Hamstrings Muscle Hypertrophy but Similar Damage Protection after Training at Long versus Short Muscle Lengths","journal":"Medicine & Science in Sports & Exercise 53(4):825-837","doi":"10.1249/MSS.0000000000002523","url":"https://pubmed.ncbi.nlm.nih.gov/33009197/","finding":"Whole-hamstring volume increased more with seated than prone curls (about 14% versus 9%); the difference involved the biarticular muscles.","limit":"Add knee-flexion work and favor seated curls when available and comfortable. This was not a direct comparison of curls versus RDLs or sliders."},
  {"id":"R12","year":2026,"authors":"Kinoshita et al.","title":"Hypertrophic Effects of Single- versus Multi-Joint Exercise: A Direct Comparison between Knee Extension and Leg Press","journal":"Medicine & Science in Sports & Exercise 58(7):1566-1580; online February 2026","doi":"10.1249/MSS.0000000000003957","url":"https://pubmed.ncbi.nlm.nih.gov/41630124/","finding":"Rectus femoris growth favored knee extension (13.2% versus 1.1%); other quadriceps regions and total quadriceps were more similar. Leg press also grew gluteus maximus and adductor magnus.","limit":"Include leg press as a compound option and leg extension as complementary quad work. The small single study does not make isolation mandatory in every short workout."},
  {"id":"R13","year":2023,"authors":"Maeo et al.","title":"Triceps brachii hypertrophy is substantially greater after elbow extension training performed in the overhead versus neutral arm position","journal":"European Journal of Sport Science 23(7):1240-1250; online 2022","doi":"10.1080/17461391.2022.2100279","url":"https://pubmed.ncbi.nlm.nih.gov/35819335/","finding":"Overhead extensions produced greater triceps growth than neutral-arm extensions in this protocol, particularly in the long head.","limit":"Retain the overhead pattern and add a cable version plus pressdowns as an alternative. The direct trial used cables, not the existing dumbbell variation."},
  {"id":"R14","year":2023,"authors":"Kinoshita et al.","title":"Triceps surae muscle hypertrophy is greater after standing versus seated calf-raise training","journal":"Frontiers in Physiology 14:1272106","doi":"10.3389/fphys.2023.1272106","url":"https://www.frontiersin.org/journals/physiology/articles/10.3389/fphys.2023.1272106/full","finding":"Standing raises produced substantially more gastrocnemius growth; soleus growth was similar between conditions.","limit":"Prioritize a straight-knee calf option. Seated raises remain useful alternatives, but the trial does not show that seated work is required for soleus growth."},
  {"id":"R15","year":2023,"authors":"Plotkin et al.","title":"Hip thrust and back squat training elicit similar gluteus muscle hypertrophy and transfer similarly to the deadlift","journal":"Frontiers in Physiology 14:1279170","doi":"10.3389/fphys.2023.1279170","url":"https://www.frontiersin.org/journals/physiology/articles/10.3389/fphys.2023.1279170/full","finding":"Gluteal hypertrophy was similar, thigh growth favored squats, and strength gains favored the practiced exercise.","limit":"Squats and hip thrusts are legitimate choices for different priorities. Acute muscle-activation rankings alone should not determine the catalog."},
  {"id":"R16","year":2025,"authors":"Larsen et al.","title":"Dumbbell versus cable lateral raises for lateral deltoid hypertrophy: an experimental study","journal":"Frontiers in Physiology 16:1611468","doi":"10.3389/fphys.2025.1611468","url":"https://www.frontiersin.org/journals/physiology/articles/10.3389/fphys.2025.1611468/full","finding":"Dumbbells and cables produced similar lateral-deltoid growth under these conditions.","limit":"Add cables for preference and availability, not as a superior level unlocked after dumbbells. Different motion ranges were not tested."},
  {"id":"R17","year":2025,"authors":"Wolf et al.","title":"Lengthened partial repetitions elicit similar muscular adaptations as full range of motion repetitions during resistance training in trained individuals","journal":"PeerJ","url":"https://pubmed.ncbi.nlm.nih.gov/39959841/","finding":"Lengthened partials and full-range training produced similar measured arm hypertrophy and pulldown strength-endurance changes.","limit":"Use controlled, tolerable full range by default; retain lengthened partials as an optional technique. This is not evidence for replacing all full-range training."},
  {"id":"R18","year":2024,"authors":"Singer et al.","title":"Give it a rest: a systematic review with Bayesian meta-analysis on the effect of inter-set rest interval duration on muscle hypertrophy","journal":"Frontiers in Sports and Active Living 6:1429789","doi":"10.3389/fspor.2024.1429789","url":"https://www.frontiersin.org/journals/sports-and-active-living/articles/10.3389/fspor.2024.1429789/full","finding":"Results suggested a small benefit from resting more than 60 seconds; additional differences above 90 seconds were not clearly detected.","limit":"Do not achieve short sessions by indiscriminately removing rest. Adjust rest to restore useful performance rather than treating one duration as a universal optimum."},
  {"id":"R19","year":2024,"authors":"Ramos-Campo et al.","title":"Efficacy of Split Versus Full-Body Resistance Training on Strength and Muscle Growth: A Systematic Review With Meta-Analysis","journal":"Journal of Strength and Conditioning Research 38(7):1330-1340","url":"https://pubmed.ncbi.nlm.nih.gov/38595233/","finding":"Split and full-body routines produced similar outcomes when training volume was matched.","limit":"Default to full-body sessions for two or three available days; allow splits for preference and scheduling. Full-body is a convenience choice, not a universal physiological winner."},
  {"id":"R20","year":2022,"authors":"Kassiano et al.","title":"Does Varying Resistance Exercises Promote Superior Muscle Hypertrophy and Strength Gains? A Systematic Review","journal":"Journal of Strength and Conditioning Research 36(6):1753-1762","doi":"10.1519/JSC.0000000000004258","url":"https://pubmed.ncbi.nlm.nih.gov/35438660/","finding":"Planned variation may aid regional development; excessive random variation and redundant choices can impede useful training continuity.","limit":"Keep a small stable exercise menu across a training block. Change exercises for a reason, with a separate performance history for each variation."},
  {"id":"R21","year":2026,"authors":"Advanced-methods network meta-analysis","title":"The Effects of Advanced Resistance Training Prescription Methods on Strength, Power, Hypertrophy, and Performance Adaptations in Healthy Adults: A Systematic Review and Bayesian Network Meta-analysis","journal":"Sports Medicine; published April 8, 2026","doi":"10.1007/s40279-026-02428-1","url":"https://link.springer.com/article/10.1007/s40279-026-02428-1","finding":"Advanced methods did not consistently outperform traditional training for strength, power, or hypertrophy in untrained to moderately trained adults.","limit":"Treat techniques such as advanced set structures as optional tools; simple progression remains a sound default. Highly trained populations were less well represented."},
  {"id":"R22","year":2020,"authors":"Bull et al. / WHO","title":"World Health Organization 2020 guidelines on physical activity and sedentary behaviour","journal":"British Journal of Sports Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/33239350/","finding":"Adults should accumulate 150-300 minutes of moderate or 75-150 minutes of vigorous aerobic activity weekly, or an equivalent mix, alongside strengthening at least twice weekly.","limit":"Count walking outside formal workouts. Short strength sessions do not automatically fulfill aerobic targets; activity below the target still has value."},
  {"id":"R23","year":2026,"authors":"Stefanovic, Werndle and Reljic","title":"Effects of High-Intensity Interval Training on Cardiorespiratory Fitness and Cardiometabolic Health in Real-World Settings: A Systematic Review and Meta-Analysis","journal":"Sports 14(7):311; July 22, 2026","doi":"10.3390/sports14070311","url":"https://pubmed.ncbi.nlm.nih.gov/42506854/","finding":"Real-world HIIT was associated with improved cardiorespiratory fitness and selected cardiometabolic outcomes.","limit":"Offer intervals on suitable modes, including bikes. Within-group pooled changes do not establish superiority over continuous training or identify a universally best interval protocol."},
  {"id":"R24","year":2026,"authors":"Resistance-training variables review","title":"Effects of resistance training variables on muscle hypertrophy in resistance-trained individuals: A systematic review","journal":"Journal of Bodywork and Movement Therapies 48:1149-1152; online August 21, 2026","doi":"10.1016/j.jbmt.2026.08.025","url":"https://www.sciencedirect.com/science/article/pii/S1360859226002561","finding":"The review emphasizes training volume and effort as central contributors, with less consistent independent effects of other variables.","limit":"Recent corroboration, given limited weight because the synthesis is small. Do not optimize raw tonnage across exercises: load times reps is not a comparable hypertrophy dose across movements."},
];

